            "issue",
            "issue_and_projects"
          ]
        },
        "project_aliases": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "labels": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "milestone": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "description": "task specification確定後の外部publication intent。project_aliases空かつmode=issue_and_projectsの場合はrepo configのdefault/auto-add targetを使う。draft/unconfirmed/evaluation非pass/readiness非completeではmodeに関わらず外部write禁止。"
    },
    "github_project_linkages": {
      "type": "array",
      "uniqueItems": true,
      "description": "1つのtask/issueを複数GitHub Projects v2へ関連付ける永続linkage。field valueのupdatedAtは競合hintに使い、削除/欠落/renameも扱うcanonical 3-way baseはfield_snapshotとする。Beads mirrorはviewer-onlyで本linkageのcustom-field同期対象外。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "project_alias",
          "owner_type",
          "owner_login",
          "project_number",
          "project_id",
          "item_id",
          "sync_state",
          "field_snapshot",
          "linked_at",
          "last_synced_at"
        ],
        "properties": {
          "project_alias": {
            "type": "string",
            "minLength": 1
          },
          "owner_type": {
            "type": "string",
            "enum": [
              "organization",
              "user"
            ]
          },
          "owner_login": {
            "type": "string",
            "minLength": 1
          },
          "project_number": {
            "type": "integer",
            "minimum": 1
          },
          "project_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "item_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "sync_state": {
            "type": "string",
            "enum": [
              "unlinked",
              "linked",
              "synced",
              "pending_retry",
              "conflict",
              "detached"
            ]
          },
          "field_snapshot": {
            "type": "object",
            "additionalProperties": {
              "type": [
                "string",
                "number",
                "boolean",
                "null"
              ]
            }
          },
          "linked_at": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "last_synced_at": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "last_error_code": {
            "type": [
              "string",
              "null"
            ]
          }
        }
      }
    },
    "pull_request_linkages": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "repo",
          "pr_number",
          "url",
          "base_branch",
          "head_branch",
          "state",
          "merged_at",
          "merge_commit_sha",
          "linked_at",
          "closing_reference_verified"
        ],
        "properties": {
          "repo": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"
          },
          "pr_number": {
            "type": "integer",
            "minimum": 1
          },
          "url": {
            "type": "string",
            "format": "uri"
          },
          "base_branch": {
            "type": "string",
            "minLength": 1
          },
          "head_branch": {
            "type": "string",
            "minLength": 1
          },
          "state": {
            "type": "string",
            "enum": [
              "open",
              "closed_unmerged",
              "merged"
            ]
          },
          "merged_at": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "merge_commit_sha": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^[0-9a-f]{40}$"
          },
          "linked_at": {
            "type": "string",
            "format": "date-time"
          },
          "closing_reference_verified": {
            "type": "boolean"
          }
        }
      },
      "description": "task/IssueへlinkされたPR fact。closed_unmergedとmergedを分離し、default branch向けclosing referenceが確認できたmerged PRだけを自動完了evidenceに使う。"
    },
    "execution_contexts": {
      "type": "array",
      "items": {
        "type": "object",
